mapper.select:
/* selectMasterMdCmCatalogRecharterList */ SELECT A.RC_NO , A.RC_SEQ , A.REVISION , A.AGENT ,(SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = A.AGENT) AS AGENT_NM , A.BUYER ,(SELECT CMPY.COM_NAME_LOC FROM ICOMCMPY CMPY WHERE CMPY.COM_CODE = A.BUYER) AS BUYER_NM , A.BYIT_COMORG_CODE , A.BUYER_ITEM_NO , A.CONTRACT_NO , A.CONTRACT_SEQ , A.RC_TYPE , (SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'RC01' AND COD.CODE = A.RC_TYPE) AS RC_TEXT , A.ATOB_DATE , A.ATOS_DATE , A.STOA_DATE , A.CLOSE_DATE , A.STOA_CLOSE_DATE , A.STOA_CLOSE_DATE AS STOA_CLOSE_DATE_2 , A.UNIT_PRICE , A.ATOB_UNIT_PRICE , A.LIST_PRICE , A.STOA_LIST_PRICE , A.A_NOTE , B.DESCRIPTION_LOC , B.SPECIFICATION , B.ORIGIN_CODE , (SELECT COD.TEXT2 FROM ICOMCOD1 COD WHERE COD.TYPE = 'M001' AND CODE = B.ORIGIN_CODE) AS ORIGIN_NM , C.MAKER_NAME , C.UNIT_MEASURE , C.MAKER_PART_NO , C.MIN_ORDER_QTY , C.PUR_UNIT_QTY , A.ADD_USER_ID , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = A.ADD_USER_ID) USER_NM , (SELECT USR.PHONE_NUMBER FROM ICOMLUSR USR WHERE USR.USER_ID = A.ADD_USER_ID) USER_PHONE_NUMBER , NVL(D.RATE_GUBUN,'B') AS RATE_GUBUN , NVL(D.RATE, 3) AS RATE , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = A.STOA_USER_ID) AS STOA_USER_NM , (SELECT USR.PHONE_NUMBER FROM ICOMLUSR USR WHERE USR.USER_ID = A.STOA_USER_ID) AS STOA_USER_PHONE , (SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'CC01' AND COD.CODE = A.G_NOTE) AS G_NOTE , A.S_NOTE , C.UNIT_PRICE AS RE_UNIT_PRICE , C.LIST_PRICE AS RE_LIST_PRICE , C.SELL_CLOSE_DATE AS RE_TO_DATE , C.BUY_CLOSE_DATE AS RE_BUY_CLOSE_DATE , C.SELL_CLOSE_DATE AS RE_SELL_CLOSE_DATE , C.LAST_PO_DATE , ROUND(((A.STOA_LIST_PRICE - C.LIST_PRICE) / C.LIST_PRICE * 100), 2) AS INCR_RATE , A.UNIT_PRICE_CHANGE_REASON AS UNIT_PRICE_CHANGE_REASON , A.LIST_PRICE_CHANGE_REASON AS LIST_PRICE_CHANGE_REASON FROM KEP_RCDT A, ICOMBYIT B, ICOMCQDT C, KEP_BUYER_RATE D WHERE A.BYIT_COMORG_CODE = B.BUYER AND A.BYIT_COMORG_CODE = C.BUYER AND B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND B.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND A.BUYER = D.BUYER(+) AND B.STATUS != 'D' AND C.STATUS != 'D' AND A.RC_TYPE != 'O' AND A.ATOS_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND A.BUYER = #{st_buyer_code}
AND A.AGENT = #{st_agent_code}
AND A.BUYER_ITEM_NO LIKE '%'||#{st_buyer_item_no}||'%'
AND A.RC_TYPE = #{st_rc_type}
AND A.RC_NO LIKE '%'||#{st_rc_no}||'%'
AND B.DESCRIPTION_LOC LIKE '%'||#{st_desc}||'%'
AND B.SPECIFICATION LIKE '%'||#{st_sepc}||'%'
AND DECODE(C.UNIT_PRICE,A.ATOB_UNIT_PRICE,'N','Y') = #{st_unit_price_yn}
AND DECODE(C.LIST_PRICE,A.STOA_LIST_PRICE,'N','Y') = #{st_price_yn}
AND A.ADD_USER_ID = #{st_mng_id}
AND ROUND(((A.STOA_LIST_PRICE - C.LIST_PRICE) / C.LIST_PRICE * 100), 2) >= #{st_incr_rate}
AND ROUND(((A.STOA_LIST_PRICE - C.LIST_PRICE) / C.LIST_PRICE * 100), 2) <= #{st_incr_rate}
ORDER BY A.RC_NO, A.RC_SEQ

mapper.update:

		 /*saveMasterMdCmCatalogRecharter*/
		 	UPDATE KEP_RCDT A                                   
               SET CHANGE_DATE= SYSDATE
                   , ATOB_UNIT_PRICE = #{ATOB_UNIT_PRICE}
                   , UNIT_PRICE_CHANGE_REASON = #{UNIT_PRICE_CHANGE_REASON}
             WHERE A.RC_NO = #{RC_NO}
               AND A.RC_SEQ = #{RC_SEQ}
               AND A.REVISION = #{REVISION}    
               AND A.AGENT = #{AGENT}
               AND A.BUYER = #{BUYER}


		 /*cancleMasterMdCmCatalogRecharter*/
		 	UPDATE KEP_RCDT A                                   
               SET CHANGE_DATE= SYSDATE
                   , CHANGE_USER_ID = #{st_user_id}
                   ,  RC_TYPE = 'D'
             WHERE A.RC_NO = #{RC_NO}
               AND A.RC_SEQ = #{RC_SEQ}
               AND A.REVISION = #{REVISION}    
               AND A.AGENT = #{AGENT}
               AND A.BUYER = #{BUYER}


		 /*updateMasterMdCmCatalogRecharterRevision*/
		 	UPDATE KEP_RCDT A                                   
               SET CHANGE_DATE= SYSDATE
                   , CHANGE_USER_ID = #{st_user_id}
                   ,  RC_TYPE = 'O'
             WHERE A.RC_NO = #{RC_NO}
               AND A.RC_SEQ = #{RC_SEQ}
               AND A.REVISION = #{REVISION}    
               AND A.AGENT = #{AGENT}
               AND A.BUYER = #{BUYER}


 /*insertMasterMdCmCatalogRecharterRevision*/
  INSERT INTO KEP_RCDT
  ( RC_NO
  , RC_SEQ
  , REVISION
  , AGENT
  , BUYER
  , BYIT_COMORG_CODE
  , BUYER_ITEM_NO
  , CONTRACT_NO
  , CONTRACT_SEQ
  , RC_TYPE
  , ATOB_DATE
  , ATOS_DATE
  , CLOSE_DATE
  , STOA_CLOSE_DATE
  , STOA_LIST_PRICE
  , A_NOTE
  , ADD_DATE
  , ADD_USER_ID
  , CHANGE_DATE
  , CHANGE_USER_ID
  ) VALUES
  (
    #{RC_NO}
    , #{RC_SEQ}
    , (SELECT MAX(RCDT.REVISION)+1 FROM KEP_RCDT RCDT
		WHERE RCDT.RC_NO = #{RC_NO}
		AND RCDT.RC_SEQ = #{RC_SEQ})
    , #{AGENT}
    , #{BUYER}
    , #{BYIT_COMORG_CODE}
    , #{BUYER_ITEM_NO}
    , #{CONTRACT_NO}
    , #{CONTRACT_SEQ}
    , 'C'
    , #{ATOB_DATE}
    , TO_CHAR(SYSDATE, 'YYYYMMDD')
    , #{CLOSE_DATE}
    , #{STOA_CLOSE_DATE}
    , #{LIST_PRICE}
    , #{A_NOTE}
    , SYSDATE
    , #{st_user_id}
    , SYSDATE
    , #{st_user_id}
  )


		 /*deleteMasterMdCmKepmgpdtRecharter*/
		 	UPDATE KEPMGPDT A                                   
               SET CHANGE_DATE= SYSDATE
                   ,  STATUS = 'D'
             WHERE A.BUYER = #{BUYER}
               AND A.QUOTATION_NO = #{RC_NO}
               AND A.QUOTATION_SEQ = #{RC_SEQ}
               AND A.REVISION = #{REVISION}    
               AND A.BUYER_ITEM_NO = #{BUYER_ITEM_NO}
               AND A.STATUS = 'C'


		 /*deleteMasterMdCmKepmghhdRecharter*/
		 	UPDATE KEPMGPHD A                                   
               SET CHANGE_DATE= SYSDATE
                   ,  STATUS = 'D'
             WHERE (A.BUYER, A.PM_NO) IN (
             	SELECT B.BUYER, B.PM_NO FROM KEPMGPDT B
             	WHERE B.BUYER = #{BUYER}
               AND B.QUOTATION_NO = #{RC_NO}
               AND B.QUOTATION_SEQ = #{RC_SEQ}
               AND B.REVISION = #{REVISION}    
               AND B.BUYER_ITEM_NO = #{BUYER_ITEM_NO}
               AND B.STATUS = 'D'    
             )


		 /*approvalMasterMdCmCatalogRecharter*/
		 	UPDATE KEP_RCDT A                                   
               SET CHANGE_DATE= SYSDATE
                   , CHANGE_USER_ID = #{st_user_id}
                   ,  RC_TYPE = 'W'
             WHERE A.RC_NO = #{RC_NO}
               AND A.RC_SEQ = #{RC_SEQ}
               AND A.REVISION = #{REVISION}    
               AND A.AGENT = #{AGENT}
               AND A.BUYER = #{BUYER}
